begin;
insert into clinic_finance.accounts values ('1142','سلف العاملين','asset'),('1211','تكلفة الأصول الثابتة','asset'),('1291','مجمع إهلاك الأصول','asset'),('2131','مرتبات مستحقة','liability'),('2142','ضرائب أجور مستحقة','liability'),('2143','تأمينات عاملين مستحقة','liability'),('2144','ضرائب أخرى مستحقة','liability'),('1143','ضرائب قابلة للاسترداد','asset'),('5211','أجور وبدلات','expense'),('5221','مصروف الإهلاك','expense'),('5231','مصروف ضرائب مثبتة بمستند','expense') on conflict do nothing;
create table clinic_finance.business_requests(id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('employment','payroll','salary_payment','advance','asset','depreciation','tax','tax_payment','statutory_payment')),subject text not null,reference text not null unique,amount numeric(14,2) not null check(amount>=0 and amount::text<>'NaN'),payload jsonb not null,created_by uuid not null references public.admins(id),token uuid not null,created_at timestamptz not null default now(),status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewed_by uuid references public.admins(id),review_note text,unique(created_by,token));
create unique index finance_payroll_month on clinic_finance.business_requests(subject,(payload->>'month')) where kind='payroll' and status in ('pending','approved');
create unique index finance_depreciation_month on clinic_finance.business_requests((payload->>'asset_id'),(payload->>'month')) where kind='depreciation' and status in ('pending','approved');
create or replace function clinic_finance.employee_advance(p_subject text) returns numeric language sql stable security definer set search_path=pg_catalog,public as $$select coalesce(sum(case when kind='advance' then amount when kind='payroll' then -coalesce((payload->>'recovery')::numeric,0) else 0 end),0) from clinic_finance.business_requests where subject=p_subject and status='approved'$$;
create or replace function clinic_finance.employee_due(p_subject text) returns numeric language sql stable security definer set search_path=pg_catalog,public as $$select coalesce(sum(case when kind='payroll' then amount-coalesce((payload->>'tax')::numeric,0)-coalesce((payload->>'insurance')::numeric,0)-coalesce((payload->>'recovery')::numeric,0) when kind='salary_payment' then -amount else 0 end),0) from clinic_finance.business_requests where subject=p_subject and status='approved'$$;
create or replace function public.clinic_finance_business_command(p_action text,p_payload jsonb,p_token uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare me uuid:=clinic_finance.require_access('create');r clinic_finance.business_requests%rowtype;c clinic_finance.business_requests%rowtype;v uuid;k text:=p_payload->>'kind';sub text:=trim(p_payload->>'subject');a numeric;ded numeric;val numeric;used numeric;debit text;credit text;sh uuid;mon date;months integer;j text;
begin perform clinic_finance.lock_day();
if p_action='request' then
 select * into r from clinic_finance.business_requests where created_by=me and token=p_token;if found then if r.payload<>p_payload then raise exception 'مفتاح الطلب مستخدم لبيانات أخرى';end if;return r.id;end if;
 if coalesce(length(trim(p_payload->>'reference')),0)<2 or coalesce(length(trim(p_payload->>'note')),0)<3 or coalesce(length(sub),0)<2 then raise exception 'المعرف والمرجع وشرح المستند مطلوبة';end if;
 foreach j in array array['amount','base','allowance','tax','insurance','recovery','residual'] loop if p_payload ? j and (p_payload->>j is null or (p_payload->>j)::numeric<0 or (p_payload->>j)::numeric<>round((p_payload->>j)::numeric,2) or p_payload->>j in ('NaN','Infinity','-Infinity')) then raise exception 'مبلغ غير صالح: %',j;end if;end loop;
 a:=coalesce((p_payload->>'amount')::numeric,0);
 if k='employment' then if nullif(p_payload->>'base','') is null or nullif(p_payload->>'from','') is null or nullif(p_payload->>'to','') is null or (p_payload->>'base')::numeric<=0 or nullif(p_payload->>'employee_name','') is null or (p_payload->>'to')::date<(p_payload->>'from')::date then raise exception 'بيانات عقد الموظف غير صالحة';end if;a:=(p_payload->>'base')::numeric;
 elsif k='payroll' then select * into c from clinic_finance.business_requests where id=(p_payload->>'contract_id')::uuid and kind='employment' and status='approved' and subject=sub;if not found then raise exception 'اختر عقد موظف معتمد';end if;mon:=(p_payload->>'month')::date;if mon is null or mon<>date_trunc('month',mon)::date or mon>date_trunc('month',now())::date or mon<date_trunc('month',(c.payload->>'from')::date)::date or mon>date_trunc('month',(c.payload->>'to')::date)::date then raise exception 'شهر المرتب خارج العقد أو في المستقبل';end if;
 a:=c.amount+coalesce((p_payload->>'allowance')::numeric,0);ded:=coalesce((p_payload->>'tax')::numeric,0)+coalesce((p_payload->>'insurance')::numeric,0)+coalesce((p_payload->>'recovery')::numeric,0);if ded>a then raise exception 'الاستقطاعات تتجاوز الإجمالي';end if;
 elsif k='asset' then if p_payload->>'residual' is null or p_payload->>'months' is null or a<=0 or (p_payload->>'residual')::numeric>=a or (p_payload->>'months')::integer not between 1 and 1200 or (p_payload->>'start')::date is null then raise exception 'تكلفة الأصل وعمره وقيمته المتبقية غير صالحة';end if;
 elsif k='depreciation' then select * into c from clinic_finance.business_requests where id=(p_payload->>'asset_id')::uuid and kind='asset' and status='approved';if not found then raise exception 'الأصل غير معتمد';end if;sub:=c.subject;mon:=(p_payload->>'month')::date;select count(*),coalesce(sum(amount),0) into months,used from clinic_finance.business_requests where kind='depreciation' and status='approved' and payload->>'asset_id'=c.id::text;
 if mon is null or mon<>date_trunc('month',mon)::date or mon>date_trunc('month',now())::date or mon<>(date_trunc('month',(c.payload->>'start')::date)+make_interval(months=>months))::date then raise exception 'يجب الإهلاك شهرًا بشهر بدءًا من شهر التشغيل';end if;
 a:=least(case when months=(c.payload->>'months')::integer-1 then c.amount-(c.payload->>'residual')::numeric-used else round((c.amount-(c.payload->>'residual')::numeric)/(c.payload->>'months')::integer,2) end,c.amount-(c.payload->>'residual')::numeric-used);if a<=0 or months>=(c.payload->>'months')::integer then raise exception 'الأصل وصل حد الإهلاك';end if;
 elsif k in ('salary_payment','advance','tax','tax_payment','statutory_payment') then if a<=0 then raise exception 'المبلغ يجب أن يكون موجبًا';end if;
 else raise exception 'نوع الطلب غير معروف';end if;
 if k='advance' and not exists(select 1 from clinic_finance.business_requests where kind='employment' and status='approved' and subject=sub) then raise exception 'لا يوجد عقد معتمد لمعرف الموظف';end if;
 if k in ('salary_payment','advance','asset','tax_payment','statutory_payment') then if p_payload->>'method' not in ('cash','bank') or p_payload->>'method' is null then raise exception 'اختر قناة الصرف';end if;if p_payload->>'method'='cash' then perform clinic_finance.check_shift((p_payload->>'shift_id')::uuid);end if;end if;
 if k='tax' and coalesce(p_payload->>'direction','') not in ('payable','recoverable') then raise exception 'حدد ضريبة مستحقة أو قابلة للاسترداد حسب المستند';end if;
 insert into clinic_finance.business_requests(kind,subject,reference,amount,payload,created_by,token) values(k,sub,trim(p_payload->>'reference'),a,p_payload,me,p_token) returning id into v;
elsif p_action='review' then
 perform clinic_finance.require_access('review');select * into r from clinic_finance.business_requests where id=(p_payload->>'id')::uuid for update;if not found or r.status<>'pending' or r.created_by=me or length(trim(p_payload->>'note'))<3 then raise exception 'يلزم طلب معلق ومراجع آخر وسبب القرار';end if;v:=r.id;k:=r.kind;a:=r.amount;sub:=r.subject;
 if (p_payload->>'approve')::boolean then
 if k='employment' then if exists(select 1 from clinic_finance.business_requests x where kind='employment' and status='approved' and subject=sub and daterange((x.payload->>'from')::date,(x.payload->>'to')::date,'[]')&&daterange((r.payload->>'from')::date,(r.payload->>'to')::date,'[]')) then raise exception 'يوجد عقد موظف متداخل';end if;
 elsif k='payroll' then
 val:=coalesce((r.payload->>'recovery')::numeric,0);if val>clinic_finance.employee_advance(sub) then raise exception 'استرداد السلفة يتجاوز رصيد الموظف';end if;
 perform clinic_finance.post('payroll_gross',v,'استحقاق مرتب '||sub||' '||(r.payload->>'month'),null,'5211','2131',a);
 foreach j in array array['tax','insurance','recovery'] loop val:=coalesce((r.payload->>j)::numeric,0);if val>0 then perform clinic_finance.post('payroll_'||j,v,'استقطاع موثق من المرتب '||sub,null,'2131',case j when 'tax' then '2142' when 'insurance' then '2143' else '1142' end,val);end if;end loop;
 elsif k='depreciation' then
 select * into c from clinic_finance.business_requests where id=(r.payload->>'asset_id')::uuid;select count(*),coalesce(sum(amount),0) into months,used from clinic_finance.business_requests where kind='depreciation' and status='approved' and payload->>'asset_id'=c.id::text;
 if (r.payload->>'month')::date<>(date_trunc('month',(c.payload->>'start')::date)+make_interval(months=>months))::date or a>c.amount-(c.payload->>'residual')::numeric-used then raise exception 'تغير رصيد أو تسلسل الإهلاك';end if;perform clinic_finance.post('depreciation',v,'إهلاك '||sub||' '||(r.payload->>'month'),null,'5221','1291',a);
 elsif k='tax' then perform clinic_finance.post('tax_assessment',v,'إثبات ضريبة '||r.reference,null,case when r.payload->>'direction'='recoverable' then '1143' else '5231' end,case when r.payload->>'direction'='recoverable' then '5231' else '2144' end,a);
 else
 sh:=null;if r.payload->>'method'='cash' then sh:=(r.payload->>'shift_id')::uuid;perform clinic_finance.check_shift(sh,false);end if;credit:=case r.payload->>'method' when 'cash' then '1111' else '1112' end;
 if k='salary_payment' then if a>clinic_finance.employee_due(sub) then raise exception 'الصرف يتجاوز صافي المرتبات المستحقة';end if;debit:='2131';
 elsif k='advance' then debit:='1142';
 elsif k='asset' then debit:='1211';
 elsif k='statutory_payment' then debit:=r.payload->>'account';if debit not in ('2141','2142','2143') or debit is null then raise exception 'اختر حساب ضريبة الأجور أو التأمينات';end if;select coalesce(sum(l.credit-l.debit),0) into used from clinic_finance.lines l where l.account=r.payload->>'account';if a>used then raise exception 'السداد يتجاوز الالتزام المثبت';end if;
 elsif k='tax_payment' then select * into c from clinic_finance.business_requests where id=(r.payload->>'tax_id')::uuid and kind='tax' and status='approved' and payload->>'direction'='payable';if not found then raise exception 'اختر ضريبة مستحقة معتمدة';end if;select coalesce(sum(amount),0) into used from clinic_finance.business_requests where kind='tax_payment' and status='approved' and payload->>'tax_id'=c.id::text;if a>c.amount-used then raise exception 'السداد يتجاوز الضريبة المستحقة';end if;debit:='2144';end if;
 perform clinic_finance.post('business_'||k,v,r.reference||' — '||sub,sh,debit,credit,a);
 end if;end if;
 update clinic_finance.business_requests set status=case when (p_payload->>'approve')::boolean then 'approved' else 'rejected' end,reviewed_by=me,review_note=p_payload->>'note' where id=v;
else raise exception 'إجراء غير معروف';end if;
insert into clinic_finance.audit(actor,action,entity_id) values(me,'business_'||p_action,v);return v;end $$;
alter function public.clinic_finance_snapshot(date,date,integer) set schema clinic_finance;
alter function clinic_finance.clinic_finance_snapshot(date,date,integer) rename to business_snapshot_base;
create function public.clinic_finance_snapshot(p_from date,p_to date,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare v jsonb:=clinic_finance.business_snapshot_base(p_from,p_to,p_offset);me uuid:=clinic_finance.require_access('view');begin
if clinic_finance.allowed('review') or clinic_finance.allowed('create') then v:=v||jsonb_build_object('business_requests',(select coalesce(jsonb_agg(x),'[]') from(select * from clinic_finance.business_requests where clinic_finance.allowed('review') or created_by=me order by created_at desc limit 200 offset p_offset)x),'employment_contracts',(select coalesce(jsonb_agg(x),'[]') from(select id,subject,amount,payload from clinic_finance.business_requests where kind='employment' and status='approved' and (clinic_finance.allowed('review') or created_by=me))x),'fixed_assets',(select coalesce(jsonb_agg(x),'[]') from(select c.id,c.subject,c.amount,c.payload,c.amount-coalesce((select sum(amount) from clinic_finance.business_requests where kind='depreciation' and status='approved' and payload->>'asset_id'=c.id::text),0) book_value from clinic_finance.business_requests c where c.kind='asset' and c.status='approved' and (clinic_finance.allowed('review') or c.created_by=me))x),'employee_balances',(select coalesce(jsonb_agg(x),'[]') from(select distinct subject,clinic_finance.employee_advance(subject) advance,clinic_finance.employee_due(subject) due from clinic_finance.business_requests where kind in ('employment','payroll','advance') and status='approved' and (clinic_finance.allowed('review') or created_by=me))x));end if;return v;end $$;
alter table clinic_finance.business_requests enable row level security;
revoke all on all tables in schema clinic_finance from public,anon,authenticated;
revoke all on all functions in schema clinic_finance from public,anon,authenticated;
revoke all on function public.clinic_finance_business_command(text,jsonb,uuid),public.clinic_finance_snapshot(date,date,integer) from public,anon;
grant execute on function public.clinic_finance_business_command(text,jsonb,uuid),public.clinic_finance_snapshot(date,date,integer) to authenticated;
commit;
